import{_ as o,o as t,c as p,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Keynote- Ceph Developers AMA- Meet the Minds Behind Open Source Ceph","description":"","frontmatter":{"title":"Keynote- Ceph Developers AMA- Meet the Minds Behind Open Source Ceph","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","分布式存储","开源","开发者问答","存储技术"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_Ceph_Developers_AMA_-_Meet_the_Minds_Behind_Open_Source_Ceph.md","filePath":"posts/2025/Keynote_-_Ceph_Developers_AMA_-_Meet_the_Minds_Behind_Open_Source_Ceph.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Keynote_-_Ceph_Developers_AMA_-_Meet_the_Minds_Behind_Open_Source_Ceph.md"};function i(l,e,s,a,_,h){return t(),p("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要-ceph开发者问答环节" tabindex="-1">会议纪要：Ceph开发者问答环节 <a class="header-anchor" href="#会议纪要-ceph开发者问答环节" aria-label="Permalink to &quot;会议纪要：Ceph开发者问答环节&quot;">​</a></h3><p><strong>会议时间</strong>：2023年某月某日<br><strong>参会人员</strong>：Ceph核心开发者团队及社区成员<br><strong>会议主题</strong>：Ceph开发者问答环节，讨论Ceph的最新进展、技术问题及未来发展方向。</p><h4 id="主要讨论内容与决定事项" tabindex="-1">主要讨论内容与决定事项： <a class="header-anchor" href="#主要讨论内容与决定事项" aria-label="Permalink to &quot;主要讨论内容与决定事项：&quot;">​</a></h4><ol><li><p><strong>mclock调度器</strong>：mclock调度器作为默认的OSD调度器，在大规模生产环境中遇到了问题，特别是在恢复、回填和清理操作中。开发团队已修复部分问题，并计划继续优化，特别是针对大规模集群的性能和稳定性。</p></li><li><p><strong>Ceph集群的扩展性</strong>：讨论了Ceph集群的最大扩展性，目前最大测试集群为10,000个OSD，实际生产环境中最大已知的集群规模为6,500个OSD。开发团队鼓励社区成员继续测试并报告更大规模的集群表现。</p></li><li><p><strong>upmap与PG remapper</strong>：社区成员询问了upmap和PG remapper的使用场景和稳定性问题。开发团队计划将这些工具集成到Ceph的Balancer中，以简化大规模数据迁移的操作。</p></li><li><p><strong>多存储层自动数据放置</strong>：社区成员询问了Ceph是否计划自动决定数据在不同存储层之间的放置。开发团队认为这是一个值得探索的方向，但需要更多的讨论和实验。</p></li><li><p><strong>CephFS的一致性与警告信息</strong>：社区成员询问了CephFS的一致性问题，特别是出现故障时如何减少对用户的惊吓。开发团队将继续优化CephFS的警告系统，以减少用户的焦虑。</p></li><li><p><strong>Rook与Ceph ADM的角色</strong>：讨论了Rook和Ceph ADM在未来是否会支持更复杂的操作，如大规模硬件更换或操作系统升级。Rook将继续优化与Kubernetes的集成，而Ceph ADM将探索如何简化这些操作。</p></li><li><p><strong>Crimson与SeaStore的未来</strong>：讨论了Crimson和SeaStore的未来发展方向，特别是是否将继续支持HDD。Crimson将继续优化性能，同时保持对HDD的支持。</p></li><li><p><strong>IPv6支持与Telemetry</strong>：社区成员询问了Ceph是否计划支持IPv6的Telemetry端点。开发团队将优先解决IPv6的Telemetry支持问题。</p></li><li><p><strong>RBD镜像与命名空间配额</strong>：社区成员询问了RBD是否计划支持命名空间配额。开发团队将考虑在未来版本中引入RBD命名空间配额支持。</p></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>鼓励社区成员提供更多反馈，特别是关于mclock在大规模集群中的表现。</li><li>开发团队将继续优化Balancer，使其能够更好地处理大规模数据迁移。</li><li>开发团队将考虑在未来版本中引入更多自动化数据放置功能。</li><li>社区成员被鼓励报告任何仍然令人困惑的警告信息。</li><li>开发团队鼓励社区成员提出具体需求，以便在未来版本中实现Rook和Ceph ADM的功能。</li><li>开发团队将继续改进Crimson和SeaStore的性能和稳定性。</li><li>社区成员被鼓励继续关注IPv6支持的进展。</li><li>开发团队将考虑在未来版本中引入RBD命名空间配额支持。</li></ul><p><strong>总结</strong>：本次会议讨论了Ceph的多个关键技术问题，包括mclock调度器、集群扩展性、数据迁移工具、存储层自动放置、CephFS一致性、Rook与Ceph ADM的角色、Crimson与SeaStore的未来、IPv6支持以及RBD镜像功能。开发团队将继续优化这些功能，并鼓励社区成员提供反馈和需求。</p>',7)])])}const d=o(n,[["render",i]]);export{c as __pageData,d as default};
